{
  "diagnoses": [
    {
      "id": "wf2-semantic-contract-incomplete",
      "summary": "Workflow 2’s “Semantic Contract Gate for Keyed Event Aggregations” is incomplete: it promises three predicates but only defines #1, omitting the completion-event predicate and the output-eligibility/emission predicate.",
      "evidence": "In `senior-data-engineer/SKILL.md` under “#### Semantic Contract Gate for Keyed Event Aggregations”, the text says “write down and preserve three separate predicates:” but only item “1. Contributing-event predicate” is present; items 2 and 3 are missing (blank spacing follows).",
      "impact": "Encourages implementers to (a) guess job completion semantics, and/or (b) emit results for keys that never reach a terminal lifecycle event. This directly conflicts with the trial’s requirements to base completion on schema docs and to output only for finished jobs."
    },
    {
      "id": "wf2-output-qualification-not-specified",
      "summary": "Workflow 2 lacks an explicit rule that result emission must be gated by lifecycle completion (i.e., output only when the key/job is finished), which is required in this trial.",
      "evidence": "The Workflow 2 section contains general streaming pipeline steps, but does not state a concrete “emit only for completed keys” rule; the only nearby guidance is the incomplete predicate list and a generic fixture-validation paragraph.",
      "impact": "Implementations may output partial/ongoing aggregates, producing extra jobIds (unfinished jobs) and failing evaluation that compares per-jobId counts only for finished jobs."
    }
  ],
  "affected_files": [
    "senior-data-engineer/SKILL.md"
  ],
  "repair_plan": [
    {
      "step": 1,
      "file": "senior-data-engineer/SKILL.md",
      "change": "Complete the “Semantic Contract Gate for Keyed Event Aggregations” by adding the missing predicates #2 and #3, keeping #1 intact.",
      "details": [
        "Add **2. Completion-event predicate**: precisely define which lifecycle/terminal event types qualify a key (e.g., jobId) as “finished”, and require that these event types be sourced from the relevant schema/documentation rather than guessed.",
        "Add **3. Output-eligibility / emission predicate**: define when to emit results (only after completion predicate is satisfied) and ensure exactly-once emission per key (e.g., via state + timer/finalization rule)."
      ]
    },
    {
      "step": 2,
      "file": "senior-data-engineer/SKILL.md",
      "change": "Add an explicit ‘results output qualification’ rule to Workflow 2 near the semantic gate section.",
      "details": [
        "State that keys without a valid completion/terminal event **must not be emitted**, even if activity events exist.",
        "Recommend validating both key set and aggregate values (positive + negative fixtures) specifically covering: (a) activity but no completion => no output; (b) completion but no activity => defined behavior (typically output 0 only if required, otherwise omit; leave decision to task requirements)."
      ]
    },
    {
      "step": 3,
      "file": "senior-data-engineer/SKILL.md",
      "change": "Preserve and minimally extend the existing fixture-validation paragraph to reference the new predicates.",
      "details": [
        "Update the fixture checklist to explicitly mention verifying: completion-event predicate correctness and output-eligibility predicate correctness, in addition to contributing-event correctness."
      ]
    }
  ],
  "preservation_constraints": [
    "Do not modify unrelated workflows, tooling sections, metadata headers, licensing text, or attachments.",
    "Keep the overall structure and wording style of `senior-data-engineer/SKILL.md`; apply minimal, localized edits around Workflow 2.",
    "Do not add trial-specific code solutions; only repair reusable guidance so it correctly specifies completion detection and output qualification requirements.",
    "Do not change class names, pom references, or any task-specific implementation details outside documentation."
  ],
  "confidence": 0.84
}
